ient(145deg,#101a38,#081021)}.share-tag{display:inline-block;font-size:8px;text-transform:uppercase;letter-spacing:.12em;color:#7f94ff;margin-bottom:5px}.typing{height:25px;color:#6f80a4;font-size:10px}.composer{display:flex;gap:8px}.composer input{flex:1;background:#080f20;border:1px solid #263554;color:#fff;border-radius:11px;padding:11px;outline:none}.composer button{border:0;border-radius:11px;padding:0 16px;background:#586cff;color:#fff;font-weight:800}.stat{display:flex;justify-content:space-between;padding:9px 0;border-bottom:1px solid #1a2640;font-size:11px}.stat:last-child{border:0}.green{color:#61f2a0}.purple{color:#aebaff}.meter{height:6px;background:#080e1c;border-radius:20px;overflow:hidden;margin:6px 0 12px}.meter i{display:block;height:100%;width:var(--w);background:linear-gradient(90deg,#5269ee,#a36fff)}.thought{padding:10px;border-left:2px solid #6173eb;background:#080f20;border-radius:0 10px 10px 0;color:#8998b8;font-size:10px;line-height:1.55;margin-top:10px}.note{color:#536482;font-size:9px;line-height:1.5;margin-top:13px}@keyframes in{from{opacity:0;transform:translateY(7px)}to{opacity:1;transform:none}}@media(max-width:1000px){.layout{grid-template-columns:220px 1fr}.right{display:none}}@media(max-width:700px){.layout{grid-template-columns:1fr}.rooms{display:none}}
